/**
 * True once a deleted workspace's grace period has closed at `now`. From that
 * instant it is gone for good, whether or not the retention sweep has purged
 * its rows yet.
 */
export function isDeletedWorkspaceExpired(
  org: Organization,
  now: Date = new Date(),
): boolean {
  if (org.archivedAt === null) return false;
  const deletedAt = Date.parse(org.archivedAt);
  return now.getTime() - deletedAt >= DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug. The workspace is kept, inert,
 * for `DELETED_WORKSPACE_RETENTION_DAYS`; its owner can restore it until then,
 * after which the retention sweep purges it.
 */""")
