    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}""", """  assertNotArchived("Organization", org.id, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  const deleted = await orgRepo.archiveOrg(input.orgId);

  const payload = { ...envelope(deleted.id, actor.userId), slug: deleted.slug };
  await recordOrganizationEvent("organization.deleted", payload);
  await emit("organization.deleted", payload);

  return deleted;
}

/**
 * Brings a deleted workspace back inside its grace period. No `Actor` can be
 * resolved for a deleted workspace — sign-in is refused — so the caller is
 * identified by user id and their membership is looked up here.
 *
 * A workspace the caller cannot see (unknown, not a member, or past its
 * window) is reported as not found rather than forbidden, so the call cannot
 * be used to probe for other tenants' workspaces.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
