import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { getDb, organizations, members, projects, sessions } from "@/server/db";
import { eq } from "drizzle-orm";
import * as orgService from "@/server/services/organization-service";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import { notify } from "@/server/services/notification-service";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { NotFoundError } from "@/server/services/_support";
import { activityFilterSchema } from "@/schemas/activity";
import { registerActivityListeners } from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("lifecycle", () => {
  it("works", async () => {
    const off = registerActivityListeners();
    const t = await createTenant("life");
    await usageRepo.recomputeUsage(t.org.id);
    const seen: string[] = [];
    subscribe("organization.deleted", (p) => { seen.push(`del:${p.slug}:${p.actorId}`); });
    subscribe("organization.restored", (p) => { seen.push(`res:${p.slug}:${p.actorId}`); });
    await sessionRepo.createSession(t.userIds.owner, "tok", "2099-01-01T00:00:00.000Z");
    getDb().update(sessions).set({ activeOrgId: t.org.id }).run();

    await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug });
    expect((await sessionRepo.findSessionByTokenHash("tok"))?.activeOrgId).toBeNull();
    await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug })).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(await usageRepo.listOrgIdsForRollup(10)).not.toContain(t.org.id);
    expect(await notify(t.org.id, "member_joined", [t.userIds.admin], { title: "x", body: "x", href: "/", actorId: null })).toEqual([]);
    await expect(orgService.restoreOrganization(t.userIds.admin, t.org.id)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(orgService.restoreOrganization("nobody" as never, t.org.id)).rejects.toBeInstanceOf(NotFoundError);
    const restored = await orgService.restoreOrganization(t.userIds.owner, t.org.id);
    expect(restored.archivedAt).toBeNull();
    expect((await sessionRepo.findSessionByTokenHash("tok"))?.activeOrgId).toBe(t.org.id);
    const again = await orgService.restoreOrganization(t.userIds.owner, t.org.id);
    expect(again.archivedAt).toBeNull();
    expect(seen).toEqual([`del:life:${t.userIds.owner}`, `res:life:${t.userIds.owner}`]);
    const page = await activityRepo.listActivity({ orgId: t.org.id, limit: 50, cursor: null, action: ["organization.deleted", "organization.restored"] } as never);
    expect(page.items.map((e) => e.action).sort()).toEqual(["organization.deleted", "organization.restored"]);
    expect(activityFilterSchema.safeParse({ orgId: t.org.id, action: ["organization.deleted"] }).success).toBe(true);

    await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug });
    const deletedAt = (await orgRepo.findOrgById(t.org.id))!.archivedAt!;
    const base = Date.parse(deletedAt);
    const DAY = 86400000;
    let r = await runCleanupArchivedJob(new Date(base + 30 * DAY - 1));
    expect(await orgRepo.findOrgById(t.org.id)).not.toBeNull();
    getDb().update(organizations).set({ archivedAt: new Date(Date.now() - 30 * DAY).toISOString() }).where(eq(organizations.id, t.org.id)).run();
    await expect(orgService.restoreOrganization(t.userIds.owner, t.org.id)).rejects.toBeInstanceOf(NotFoundError);
    r = await runCleanupArchivedJob(new Date());
    expect(r.failed).toBe(0);
    expect(await orgRepo.findOrgById(t.org.id)).toBeNull();
    expect(getDb().select().from(members).where(eq(members.orgId, t.org.id)).all()).toHaveLength(0);
    expect(getDb().select().from(projects).where(eq(projects.orgId, t.org.id)).all()).toHaveLength(0);
    expect((await sessionRepo.findSessionByTokenHash("tok"))?.activeOrgId).toBeNull();
    await expect(orgService.restoreOrganization(t.userIds.owner, t.org.id)).rejects.toBeInstanceOf(NotFoundError);
    const fresh = await orgService.createOrganization(t.userIds.owner, { name: "x", slug: "life", plan: "free" });
    expect(fresh.slug).toBe("life");
    off();
  });
});
EOF
